scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap023jia == 0) @Talk0;
	If($Talkmap023jia == 1) @Talk1;
	If($Talkmap023jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：京城是个花花世界，如果不是因为金兵南下，这里以前更热闹。", 207);
	Assign($Talkmap023jia, 1);
	Return;	
@Talk1:
	Say("贾老实：人生在世，不就是图个吃喝玩乐，老弟，你说呢？", 207);
	Say("独孤剑：如果只顾自己享乐，而置国家安危于不顾，有朝一日金兵南侵，攻破城池，覆巢之下，安有完卵？", 1);
	Say("贾老实：哪里管得了那许多！", 207);
	Say("独孤剑：人人都像你这样想，大宋迟早要亡国。", 1);
	Assign($Talkmap023jia, 2);
	Return;
@Talk2:
	Say("贾老实：我最关心的就是赚钱，别的我可不想管。", 207);
	Say("独孤剑：……", 1);
	Return;

scripts.南宫彩虹对话.txt:
//向南宫彩虹取眼泪

	
	Say("南宫彩虹：你是什么人……", 29);
	Say("独孤剑：在下衡山独孤剑，冒犯姑娘了！在下有一事想请姑娘帮忙。", 1);
	Say("南宫彩虹：我与你素不相识，为什么要帮你？", 29);
	Say("独孤剑：这件事对姑娘而言易如反掌，但是对在下却帮助甚大，这种利人不损己的事，姑娘为什么不做呢？", 2);
	Say("南宫彩虹：看你能言善辩，我倒想听听你要我帮什么忙。", 29);
	Say("独孤剑：在下冒昧，想要姑娘的一滴眼泪。", 2);
	Say("南宫彩虹：这倒可笑了。公子要我的眼泪做什么？不会是为了拯救天下苍生吧？", 29);
	Say("独孤剑：这个……在下要用它来救一位姑娘。", 2);
	Say("南宫彩虹：小女子虽然常有贵人抬爱，但却不曾想到今日有人错爱至此。公子倒说说，我的眼泪怎样救人？", 29);
	Say("独孤剑：有位姑娘被采花贼掳走，去了东海的碧霞岛，但渔村的老王不肯出海。临安有一人能让老王出海，但此人想要姑娘的一滴眼泪。", 1);
	Say("南宫彩虹：天下竟有这等可笑之人！", 29);
	Say("南宫彩虹：那被掳走的姑娘是公子的什么人？", 29);
	Say("独孤剑：萍水相逢。", 1);
	Say("南宫彩虹：那么是公子看上那位姑娘了？", 29);
	Say("独孤剑：姑娘误会了，在下只是……", 4);
	Say("南宫彩虹：喜不喜欢是公子自己的事，我只是随口问问，公子又何必急于辨白呢？", 29);
	Say("独孤剑：……此事还请姑娘帮忙才好。", 4);
	Say("南宫彩虹：我倒是很想帮助公子。不过彩虹生性喜笑不喜哀，要不公子你来拧我几下，让我哭出来好不好？", 29);
	Say("独孤剑：在下……", 4);
	Say("南宫彩虹：呵呵，看公子这样为难……这样吧，我是不会随便将眼泪赠给那些庸夫俗子的，但看在公子的面上，我这里有一个酒杯，里头有一滴清水，公子拿去给那个人，这样也解了公子的难处。", 29);
	Say("独孤剑：那……就多谢姑娘了，在下告辞！", 4);
	AddGoods("Goods404_一杯清水.ini"); 
	NpcSpecialAction("独孤剑", "mpc043.asf");
	Sleep(2000);
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map016_临安城.map");
	LoadNpc("map016.npc");
	LoadObj("map016.obj");
	SetPlayerPos(26, 134);
	SetPlayerDir(0);
	FadeIn();
	StopMusic();
	PlayMusic("闲步.mp3");
	Say("独孤剑：现在可以去找贾老实了……不过这位南宫姑娘倒是有些奇怪。", 1);
	Memo("施展轻功跳入怡春院，见到南宫彩虹，得到一杯清水。");
	Assign($Event, 110);
	Return;

