scripts.妓女秋雨对话.txt:
// 和妓女秋雨的对话

	If ($Eventqiuyu == 0) @Eventqiuyu0;
	If ($Eventqiuyu == 1) @Eventqiuyu1;
	If ($Eventqiuyu == 2) @Eventqiuyu2;
	
@Eventqiuyu0:
	Say("秋雨：春花秋月何时了，往事知多少？小楼昨夜又东风，故国不堪回首月明中……想我大宋内忧外患，不知这纸醉金迷的日子还能维持多久？", 0);
	Say("独孤剑：一个青楼女子竟也知道感伤国事，外面那些寻欢作乐的须眉男子真应该感到汗颜。", 1);
	Say("秋雨：看公子是个侠义之人，小女子有一事相托，不知公子肯应承否？", 0);
	
	Memo("在临安城妓院遇到一个叫秋雨的妓女，她请求独孤剑帮其寻找舅父——韩世忠将军属下的将军刘云。");
	
	Choose("独孤剑：答不答应呢？","A 答应","B 不答应", $Chooseqiuyu);
	If($Chooseqiuyu == 0) @Choose0;
	If($Chooseqiuyu == 1) @Choose1;	
	
@Choose0:
	Say("独孤剑：姑娘有事尽管说，只要在下能力所及，一定替姑娘办到。", 1);
	Say("秋雨：多谢公子！我原本也是官宦之家的小姐，家父曾是大宋军官，当年曾跟随李纲将军四处征战，后来不幸战死沙场。", 0);
	Say("秋雨：我随母亲辗转多年，来此投奔少时她定亲的夫君，不想这奸贼竟将我卖到青楼，我母亲一气之下……", 0);
	Say("独孤剑：这等丧尽天良的事都做得出？此人是谁？", 5);
	Say("秋雨：他叫吕文才，现在是朝廷的将军，位高权重。小女子只能自叹命苦，公子不必为了我打抱不平，免得惹上麻烦……小女子只有一事相求，万望公子相助。", 0);
	Say("独孤剑：姑娘尽管吩咐。", 1);
	Say("秋雨：这块红玉乃是当年家父留给我的，是一块祖传之物。请公子收下这块红玉，倘若日后能寻我舅父刘云，希望公子能告知他小女子的下落。", 0);
	Say("独孤剑：姑娘可知他现在何处？", 1);
	Say("秋雨：我只听说他随当朝的韩世忠将军征战他乡，却不知现在何处……公子，秋儿求求你", 0);
	Say("独孤剑：救人于危难乃是我辈的本份。秋姑娘放心，在下一定替姑娘找到舅父。", 1);
	Say("秋雨：公子，你真是一个好人，小女子就静候佳音了。", 0);
	
	AddGoods("Goods402_红玉.ini");  // 得到红玉
	Assign($Eventqiuyu, 1);
	Memo("答应秋雨后，得到了她赠送的一块红玉。");
	Return;

@Choose1:
	Say("独孤剑：对不起，在下有要事在身，恐怕帮不了姑娘。", 1);
	Say("秋雨：既然如此，不提也罢。", 0);
	Assign($Eventqiuyu, 2);
	Memo("拒绝秋雨的请求后离开。");
	Return;

	
@Eventqiuyu1:
	Say("秋雨：小女子静候公子佳音。",0);
	Return;
	
@Eventqiuyu2:
	Say("秋雨：不是爱风尘，似被前缘误……唉！这样的日子不知何时是一个尽头！",0);
	Return;

scripts.妓院打手对话.txt:
